{

"kind": "propose",
"summary": "Adjust probe timeouts to accommodate slower startup of new version",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Probes timeout before application starts, causing restarts",
    "supporting": ["probe_kills", "probe_timeouts", "ev-rollout_history"],
    "contradicting": ["killed_during_startup", "crashed_on_its_own"],
    "missing": ["container_logs_tail", "revision_health"],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_broken",
    "summary": "Rollout introduced version with slower startup",
    "supporting": ["failures_came_with_rollout", "ev-rollout_history"],
    "contradicting": ["gitops_managed"],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search-api", "uid": "uid-deployment-search-api"},
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    },
    "readiness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Allow application to start before probe timeouts",
  "rationale": "Current liveness/readiness timeouts (1s) are too short for new version's startup time, causing premature kills. Increasing to 5s matches typical startup durations for search services.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-target_events", "ev-pod_states"],
  "cited_predicates": ["probe_kills", "probe_timeouts", "killed_during_startup"]
}
}
